// src/pages/Tareas.jsx
import React from "react";
import { Link } from "react-router-dom";
import Layout from "../components/Layout";
import "../pages/PageCommon.css";

export default function Tareas() {
   const tareas = [
     {
       id: 1.2,
       title: "Mapa Conceptual e Investigación",
       desc: "Análisis y documentación de conceptos fundamentales del aseguramiento de calidad",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Investigación",
       date: "2024-01-15"
     },
     {
       id: 2,
       title: "Análisis Crítico de Estándares Internacionales",
       desc: "Estudio detallado de normas ISO/IEC para calidad de software",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Análisis",
       date: "2024-02-01"
     },
     {
       id: 3,
       title: "Guía OWASP y Casos de Prueba",
       desc: "Investigación completa de vulnerabilidades web y técnicas de testing",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Seguridad",
       date: "2024-02-15"
     },
     {
       id: 4,
       title: "Tipos de Prueba",
       desc: "Clasificación y aplicación de diferentes tipos de pruebas de software",
       status: "in-progress",
       priority: "medium",
       progress: 75,
       category: "Testing",
       date: "2024-03-01"
     },
     {
       id: 5,
       title: "Técnicas de Pruebas",
       desc: "Metodologías avanzadas para pruebas funcionales y no funcionales",
       status: "pending",
       priority: "medium",
       progress: 25,
       category: "Testing",
       date: "2024-03-15"
     },
     {
       id: 6,
       title: "Unit Test - JavaScript/TypeScript",
       desc: "Desarrollo de proyecto completo con pruebas unitarias y cobertura",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Desarrollo",
       date: "2024-04-01"
     },
     {
       id: 7,
       title: "Herramientas de Testing",
       desc: "Análisis completo de herramientas para pruebas automatizadas",
       status: "in-progress",
       priority: "medium",
       progress: 60,
       category: "Herramientas",
       date: "2024-04-15"
     },
     {
       id: 8,
       title: "Registro de Errores",
       desc: "Sistema de seguimiento y gestión de bugs reportados",
       status: "completed",
       priority: "medium",
       progress: 100,
       category: "Gestión",
       date: "2024-05-01"
     },
     {
       id: 9,
       title: "Certificado QA",
       desc: "Certificación profesional en Quality Assurance",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Certificación",
       date: "2024-05-15"
     },
     {
       id: 10,
       title: "Parcial 2 - Tercera Serie",
       desc: "Evaluación práctica de conocimientos adquiridos",
       status: "completed",
       priority: "high",
       progress: 100,
       category: "Evaluación",
       date: "2024-06-01"
     },
     {
       id: 1.1,
       title: "Calculadora - Unit Test",
       desc: "Proyecto C# con pruebas unitarias y manejo de errores",
       status: "completed",
       priority: "medium",
       progress: 100,
       category: "Desarrollo",
       date: "2024-01-30"
     },
   ];

   // Calcular métricas
   const metrics = {
     total: tareas.length,
     completed: tareas.filter(t => t.status === 'completed').length,
     inProgress: tareas.filter(t => t.status === 'in-progress').length,
     pending: tareas.filter(t => t.status === 'pending').length,
   };

   const getStatusIcon = (status) => {
     switch(status) {
       case 'completed': return '✅';
       case 'in-progress': return '🔄';
       case 'pending': return '⏳';
       default: return '📋';
     }
   };

   const getPriorityIcon = (priority) => {
     switch(priority) {
       case 'high': return '🔴';
       case 'medium': return '🟡';
       case 'low': return '🟢';
       default: return '⚪';
     }
   };

  return (
    <Layout>
      <section className="page-section fade-in">
        <h1 className="page-title">
          Mis <span>Tareas</span>
        </h1>
        <p className="page-subtitle">
          Aquí encontrarás las actividades académicas y proyectos realizados.
        </p>

        <div className="content-container">
       
          <div className="content-left">
            {tareas.map((tarea) => (
              <Link
                key={tarea.id}
                to={`/tareas/${tarea.id}`}
                style={{ tetDecoration: "none", color: "inherit" }}
              >
                <div className="project-card">
                  <h2>{tarea.title}</h2>
                  <p>{tarea.desc}</p>
                </div>
              </Link>
            ))}
          </div>
          </div>
      </section>
    </Layout>
  );
}
